window.MGProseData("59f9e6d8c441d2847b945b519908fb21d0b2ba1f4464b1a26472024db6869b31",{"html":"\u003ch2>1. 良定义性、连续性、单射性与满射性\u003c/h2>\n\u003cp>记 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmi>ρ\u003c/mi>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmi>x\u003c/mi>\u003cmo stretchy=\"false\">)\u003c/mo>\u003cmo>=\u003c/mo>\u003cmi>d\u003c/mi>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmi>x\u003c/mi>\u003cmo separator=\"true\">,\u003c/mo>\u003cmn>0\u003c/mn>\u003cmo stretchy=\"false\">)\u003c/mo>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">\\rho(x)=d(x,0)\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>，并令\n\u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\" display=\"block\">\u003csemantics>\u003cmrow>\u003cmsub>\u003cmi>C\u003c/mi>\u003cmi>f\u003c/mi>\u003c/msub>\u003cmo>=\u003c/mo>\u003cmunder>\u003cmrow>\u003cmi mathvariant=\"normal\">lim sup\u003c/mi>\u003cmo>⁡\u003c/mo>\u003c/mrow>\u003cmrow>\u003cmi>n\u003c/mi>\u003cmo>→\u003c/mo>\u003cmi mathvariant=\"normal\">∞\u003c/mi>\u003c/mrow>\u003c/munder>\u003cmfrac>\u003cmrow>\u003cmi>f\u003c/mi>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmi>n\u003c/mi>\u003cmo stretchy=\"false\">)\u003c/mo>\u003c/mrow>\u003cmi>n\u003c/mi>\u003c/mfrac>\u003cmi mathvariant=\"normal\">.\u003c/mi>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">\nC_f=\\limsup_{n\\to\\infty}\\frac{f(n)}n.\n\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>\n由于 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmi>f\u003c/mi>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">f\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span> 严格递增，\u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmi>f\u003c/mi>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmi>n\u003c/mi>\u003cmo stretchy=\"false\">)\u003c/mo>\u003cmo>≥\u003c/mo>\u003cmi>n\u003c/mi>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">f(n)\\ge n\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>，故 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmsub>\u003cmi>C\u003c/mi>\u003cmi>f\u003c/mi>\u003c/msub>\u003cmo>≥\u003c/mo>\u003cmn>1\u003c/mn>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">C_f\\ge1\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>。\u003c/p>\n\u003cp>对任意 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmi>x\u003c/mi>\u003cmo>∈\u003c/mo>\u003cmi>E\u003c/mi>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">x\\in E\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>，有\n\u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\" display=\"block\">\u003csemantics>\u003cmrow>\u003cmfrac>\u003cmn>1\u003c/mn>\u003cmi>n\u003c/mi>\u003c/mfrac>\u003cmunderover>\u003cmo>∑\u003c/mo>\u003cmrow>\u003cmi>j\u003c/mi>\u003cmo>=\u003c/mo>\u003cmn>1\u003c/mn>\u003c/mrow>\u003cmi>n\u003c/mi>\u003c/munderover>\u003cmi mathvariant=\"normal\">∣\u003c/mi>\u003cmsub>\u003cmi>x\u003c/mi>\u003cmrow>\u003cmi>f\u003c/mi>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmi>j\u003c/mi>\u003cmo stretchy=\"false\">)\u003c/mo>\u003c/mrow>\u003c/msub>\u003cmi mathvariant=\"normal\">∣\u003c/mi>\u003cmo>≤\u003c/mo>\u003cmfrac>\u003cmrow>\u003cmi>f\u003c/mi>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmi>n\u003c/mi>\u003cmo stretchy=\"false\">)\u003c/mo>\u003c/mrow>\u003cmi>n\u003c/mi>\u003c/mfrac>\u003cmo>⋅\u003c/mo>\u003cmfrac>\u003cmn>1\u003c/mn>\u003cmrow>\u003cmi>f\u003c/mi>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmi>n\u003c/mi>\u003cmo stretchy=\"false\">)\u003c/mo>\u003c/mrow>\u003c/mfrac>\u003cmunderover>\u003cmo>∑\u003c/mo>\u003cmrow>\u003cmi>m\u003c/mi>\u003cmo>=\u003c/mo>\u003cmn>1\u003c/mn>\u003c/mrow>\u003cmrow>\u003cmi>f\u003c/mi>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmi>n\u003c/mi>\u003cmo stretchy=\"false\">)\u003c/mo>\u003c/mrow>\u003c/munderover>\u003cmi mathvariant=\"normal\">∣\u003c/mi>\u003cmsub>\u003cmi>x\u003c/mi>\u003cmi>m\u003c/mi>\u003c/msub>\u003cmi mathvariant=\"normal\">∣\u003c/mi>\u003cmi mathvariant=\"normal\">.\u003c/mi>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">\n\\frac1n\\sum_{j=1}^n |x_{f(j)}|\n\\le \\frac{f(n)}n\\cdot\\frac1{f(n)}\\sum_{m=1}^{f(n)}|x_m|.\n\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>\n若 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmsub>\u003cmi>C\u003c/mi>\u003cmi>f\u003c/mi>\u003c/msub>\u003cmo>\u0026lt;\u003c/mo>\u003cmi mathvariant=\"normal\">∞\u003c/mi>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">C_f\u0026lt;\\infty\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>，取上极限得 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmi>ρ\u003c/mi>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmsub>\u003cmi>P\u003c/mi>\u003cmi>f\u003c/mi>\u003c/msub>\u003cmi>x\u003c/mi>\u003cmo stretchy=\"false\">)\u003c/mo>\u003cmo>≤\u003c/mo>\u003cmsub>\u003cmi>C\u003c/mi>\u003cmi>f\u003c/mi>\u003c/msub>\u003cmi>ρ\u003c/mi>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmi>x\u003c/mi>\u003cmo stretchy=\"false\">)\u003c/mo>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">\\rho(P_fx)\\le C_f\\rho(x)\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>。将此不等式用于 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmi>x\u003c/mi>\u003cmo>−\u003c/mo>\u003cmi>y\u003c/mi>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">x-y\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>，可知 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmsub>\u003cmi>T\u003c/mi>\u003cmi>f\u003c/mi>\u003c/msub>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">T_f\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span> 良定义且连续，最小 Lipschitz 常数至多为 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmsub>\u003cmi>C\u003c/mi>\u003cmi>f\u003c/mi>\u003c/msub>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">C_f\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>。\u003c/p>\n\u003cp>固定 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmi>ε\u003c/mi>\u003cmo>\u0026gt;\u003c/mo>\u003cmn>0\u003c/mn>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">\\varepsilon\u0026gt;0\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>。选取严格递增的 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmsub>\u003cmi>n\u003c/mi>\u003cmi>i\u003c/mi>\u003c/msub>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">n_i\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>，令 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmsub>\u003cmi>m\u003c/mi>\u003cmi>i\u003c/mi>\u003c/msub>\u003cmo>=\u003c/mo>\u003cmo stretchy=\"false\">⌊\u003c/mo>\u003cmi>ε\u003c/mi>\u003cmsub>\u003cmi>n\u003c/mi>\u003cmi>i\u003c/mi>\u003c/msub>\u003cmo stretchy=\"false\">⌋\u003c/mo>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">m_i=\\lfloor\\varepsilon n_i\\rfloor\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>，使得\n\u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\" display=\"block\">\u003csemantics>\u003cmrow>\u003cmfrac>\u003cmrow>\u003cmi>f\u003c/mi>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmsub>\u003cmi>n\u003c/mi>\u003cmi>i\u003c/mi>\u003c/msub>\u003cmo stretchy=\"false\">)\u003c/mo>\u003c/mrow>\u003cmsub>\u003cmi>n\u003c/mi>\u003cmi>i\u003c/mi>\u003c/msub>\u003c/mfrac>\u003cmo>⟶\u003c/mo>\u003cmsub>\u003cmi>C\u003c/mi>\u003cmi>f\u003c/mi>\u003c/msub>\u003cmo separator=\"true\">,\u003c/mo>\u003cmspace width=\"2em\"/>\u003cmfrac>\u003cmrow>\u003cmunder>\u003cmo>∑\u003c/mo>\u003cmrow>\u003cmi>h\u003c/mi>\u003cmo>\u0026lt;\u003c/mo>\u003cmi>i\u003c/mi>\u003c/mrow>\u003c/munder>\u003cmsub>\u003cmi>m\u003c/mi>\u003cmi>h\u003c/mi>\u003c/msub>\u003c/mrow>\u003cmsub>\u003cmi>n\u003c/mi>\u003cmi>i\u003c/mi>\u003c/msub>\u003c/mfrac>\u003cmo>⟶\u003c/mo>\u003cmn>0.\u003c/mn>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">\n\\frac{f(n_i)}{n_i}\\longrightarrow C_f,\n\\qquad\n\\frac{\\sum_{h\u0026lt;i}m_h}{n_i}\\longrightarrow0.\n\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>\n具体地，在一个使 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmi>f\u003c/mi>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmi>n\u003c/mi>\u003cmo stretchy=\"false\">)\u003c/mo>\u003cmi mathvariant=\"normal\">/\u003c/mi>\u003cmi>n\u003c/mi>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">f(n)/n\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span> 趋于 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmsub>\u003cmi>C\u003c/mi>\u003cmi>f\u003c/mi>\u003c/msub>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">C_f\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span> 的子列中递归选取 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmsub>\u003cmi>n\u003c/mi>\u003cmi>i\u003c/mi>\u003c/msub>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">n_i\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>，每次要求 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmsub>\u003cmi>n\u003c/mi>\u003cmi>i\u003c/mi>\u003c/msub>\u003cmo>≥\u003c/mo>\u003cmi>i\u003c/mi>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmn>1\u003c/mn>\u003cmo>+\u003c/mo>\u003cmsub>\u003cmo>∑\u003c/mo>\u003cmrow>\u003cmi>h\u003c/mi>\u003cmo>\u0026lt;\u003c/mo>\u003cmi>i\u003c/mi>\u003c/mrow>\u003c/msub>\u003cmsub>\u003cmi>m\u003c/mi>\u003cmi>h\u003c/mi>\u003c/msub>\u003cmo stretchy=\"false\">)\u003c/mo>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">n_i\\ge i(1+\\sum_{h\u0026lt;i}m_h)\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span> 即可。令\n\u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\" display=\"block\">\u003csemantics>\u003cmrow>\u003cmi>A\u003c/mi>\u003cmo>=\u003c/mo>\u003cmunder>\u003cmo>⋃\u003c/mo>\u003cmrow>\u003cmi>i\u003c/mi>\u003cmo>≥\u003c/mo>\u003cmn>1\u003c/mn>\u003c/mrow>\u003c/munder>\u003cmo stretchy=\"false\">{\u003c/mo>\u003cmi>f\u003c/mi>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmsub>\u003cmi>n\u003c/mi>\u003cmi>i\u003c/mi>\u003c/msub>\u003cmo>+\u003c/mo>\u003cmi>j\u003c/mi>\u003cmo stretchy=\"false\">)\u003c/mo>\u003cmo>:\u003c/mo>\u003cmn>1\u003c/mn>\u003cmo>≤\u003c/mo>\u003cmi>j\u003c/mi>\u003cmo>≤\u003c/mo>\u003cmsub>\u003cmi>m\u003c/mi>\u003cmi>i\u003c/mi>\u003c/msub>\u003cmo stretchy=\"false\">}\u003c/mo>\u003cmo separator=\"true\">,\u003c/mo>\u003cmspace width=\"2em\"/>\u003cmi>x\u003c/mi>\u003cmo>=\u003c/mo>\u003cmsub>\u003cmn mathvariant=\"bold\">1\u003c/mn>\u003cmi>A\u003c/mi>\u003c/msub>\u003cmi mathvariant=\"normal\">.\u003c/mi>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">\nA=\\bigcup_{i\\ge1}\\{f(n_i+j):1\\le j\\le m_i\\},\n\\qquad x=\\mathbf 1_A.\n\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>\n当 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmi>f\u003c/mi>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmsub>\u003cmi>n\u003c/mi>\u003cmi>i\u003c/mi>\u003c/msub>\u003cmo stretchy=\"false\">)\u003c/mo>\u003cmo>≤\u003c/mo>\u003cmi>N\u003c/mi>\u003cmo>\u0026lt;\u003c/mo>\u003cmi>f\u003c/mi>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmsub>\u003cmi>n\u003c/mi>\u003cmrow>\u003cmi>i\u003c/mi>\u003cmo>+\u003c/mo>\u003cmn>1\u003c/mn>\u003c/mrow>\u003c/msub>\u003cmo stretchy=\"false\">)\u003c/mo>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">f(n_i)\\le N\u0026lt;f(n_{i+1})\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span> 时，\u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmi>A\u003c/mi>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">A\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span> 在前 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmi>N\u003c/mi>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">N\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span> 个位置中至多有 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmsub>\u003cmo>∑\u003c/mo>\u003cmrow>\u003cmi>h\u003c/mi>\u003cmo>≤\u003c/mo>\u003cmi>i\u003c/mi>\u003c/mrow>\u003c/msub>\u003cmsub>\u003cmi>m\u003c/mi>\u003cmi>h\u003c/mi>\u003c/msub>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">\\sum_{h\\le i}m_h\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span> 个元素。因此\n\u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\" display=\"block\">\u003csemantics>\u003cmrow>\u003cmi>ρ\u003c/mi>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmi>x\u003c/mi>\u003cmo stretchy=\"false\">)\u003c/mo>\u003cmo>≤\u003c/mo>\u003cmunder>\u003cmrow>\u003cmi>lim\u003c/mi>\u003cmo>⁡\u003c/mo>\u003c/mrow>\u003cmrow>\u003cmi>i\u003c/mi>\u003cmo>→\u003c/mo>\u003cmi mathvariant=\"normal\">∞\u003c/mi>\u003c/mrow>\u003c/munder>\u003cmfrac>\u003cmrow>\u003cmunder>\u003cmo>∑\u003c/mo>\u003cmrow>\u003cmi>h\u003c/mi>\u003cmo>≤\u003c/mo>\u003cmi>i\u003c/mi>\u003c/mrow>\u003c/munder>\u003cmsub>\u003cmi>m\u003c/mi>\u003cmi>h\u003c/mi>\u003c/msub>\u003c/mrow>\u003cmrow>\u003cmi>f\u003c/mi>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmsub>\u003cmi>n\u003c/mi>\u003cmi>i\u003c/mi>\u003c/msub>\u003cmo stretchy=\"false\">)\u003c/mo>\u003c/mrow>\u003c/mfrac>\u003cmo>=\u003c/mo>\u003cmfrac>\u003cmi>ε\u003c/mi>\u003cmsub>\u003cmi>C\u003c/mi>\u003cmi>f\u003c/mi>\u003c/msub>\u003c/mfrac>\u003cmo separator=\"true\">,\u003c/mo>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">\n\\rho(x)\\le \\lim_{i\\to\\infty}\\frac{\\sum_{h\\le i}m_h}{f(n_i)}\n=\\frac{\\varepsilon}{C_f},\n\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>\n其中 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmi>ε\u003c/mi>\u003cmi mathvariant=\"normal\">/\u003c/mi>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmo>+\u003c/mo>\u003cmi mathvariant=\"normal\">∞\u003c/mi>\u003cmo stretchy=\"false\">)\u003c/mo>\u003cmo>=\u003c/mo>\u003cmn>0\u003c/mn>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">\\varepsilon/(+\\infty)=0\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>。另一方面，\u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmsub>\u003cmi>P\u003c/mi>\u003cmi>f\u003c/mi>\u003c/msub>\u003cmi>x\u003c/mi>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">P_fx\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span> 在第 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmsub>\u003cmi>n\u003c/mi>\u003cmi>i\u003c/mi>\u003c/msub>\u003cmo>+\u003c/mo>\u003cmn>1\u003c/mn>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">n_i+1\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span> 至第 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmsub>\u003cmi>n\u003c/mi>\u003cmi>i\u003c/mi>\u003c/msub>\u003cmo>+\u003c/mo>\u003cmsub>\u003cmi>m\u003c/mi>\u003cmi>i\u003c/mi>\u003c/msub>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">n_i+m_i\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span> 项都等于 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmn>1\u003c/mn>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">1\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>，故\n\u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\" display=\"block\">\u003csemantics>\u003cmrow>\u003cmi>ρ\u003c/mi>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmsub>\u003cmi>P\u003c/mi>\u003cmi>f\u003c/mi>\u003c/msub>\u003cmi>x\u003c/mi>\u003cmo stretchy=\"false\">)\u003c/mo>\u003cmo>≥\u003c/mo>\u003cmunder>\u003cmrow>\u003cmi>lim\u003c/mi>\u003cmo>⁡\u003c/mo>\u003c/mrow>\u003cmrow>\u003cmi>i\u003c/mi>\u003cmo>→\u003c/mo>\u003cmi mathvariant=\"normal\">∞\u003c/mi>\u003c/mrow>\u003c/munder>\u003cmfrac>\u003cmsub>\u003cmi>m\u003c/mi>\u003cmi>i\u003c/mi>\u003c/msub>\u003cmrow>\u003cmsub>\u003cmi>n\u003c/mi>\u003cmi>i\u003c/mi>\u003c/msub>\u003cmo>+\u003c/mo>\u003cmsub>\u003cmi>m\u003c/mi>\u003cmi>i\u003c/mi>\u003c/msub>\u003c/mrow>\u003c/mfrac>\u003cmo>=\u003c/mo>\u003cmfrac>\u003cmi>ε\u003c/mi>\u003cmrow>\u003cmn>1\u003c/mn>\u003cmo>+\u003c/mo>\u003cmi>ε\u003c/mi>\u003c/mrow>\u003c/mfrac>\u003cmi mathvariant=\"normal\">.\u003c/mi>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">\n\\rho(P_fx)\\ge \\lim_{i\\to\\infty}\\frac{m_i}{n_i+m_i}\n=\\frac{\\varepsilon}{1+\\varepsilon}.\n\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>\n若 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmsub>\u003cmi>C\u003c/mi>\u003cmi>f\u003c/mi>\u003c/msub>\u003cmo>=\u003c/mo>\u003cmo>+\u003c/mo>\u003cmi mathvariant=\"normal\">∞\u003c/mi>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">C_f=+\\infty\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>，则 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmi>x\u003c/mi>\u003cmo>∼\u003c/mo>\u003cmn>0\u003c/mn>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">x\\sim0\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span> 而 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmsub>\u003cmi>P\u003c/mi>\u003cmi>f\u003c/mi>\u003c/msub>\u003cmi>x\u003c/mi>\u003cmo>≁\u003c/mo>\u003cmn>0\u003c/mn>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">P_fx\\not\\sim0\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>，所以无法诱导 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmsub>\u003cmi>T\u003c/mi>\u003cmi>f\u003c/mi>\u003c/msub>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">T_f\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>。若 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmsub>\u003cmi>C\u003c/mi>\u003cmi>f\u003c/mi>\u003c/msub>\u003cmo>\u0026lt;\u003c/mo>\u003cmi mathvariant=\"normal\">∞\u003c/mi>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">C_f\u0026lt;\\infty\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>，任何 Lipschitz 常数 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmi>K\u003c/mi>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">K\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span> 都满足\n\u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\" display=\"block\">\u003csemantics>\u003cmrow>\u003cmi>K\u003c/mi>\u003cmfrac>\u003cmi>ε\u003c/mi>\u003cmsub>\u003cmi>C\u003c/mi>\u003cmi>f\u003c/mi>\u003c/msub>\u003c/mfrac>\u003cmo>≥\u003c/mo>\u003cmfrac>\u003cmi>ε\u003c/mi>\u003cmrow>\u003cmn>1\u003c/mn>\u003cmo>+\u003c/mo>\u003cmi>ε\u003c/mi>\u003c/mrow>\u003c/mfrac>\u003cmi mathvariant=\"normal\">.\u003c/mi>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">\nK\\frac{\\varepsilon}{C_f}\\ge\\frac{\\varepsilon}{1+\\varepsilon}.\n\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>\n令 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmi>ε\u003c/mi>\u003cmo>↓\u003c/mo>\u003cmn>0\u003c/mn>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">\\varepsilon\\downarrow0\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>，得 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmi>K\u003c/mi>\u003cmo>≥\u003c/mo>\u003cmsub>\u003cmi>C\u003c/mi>\u003cmi>f\u003c/mi>\u003c/msub>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">K\\ge C_f\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>。因此，\u003cstrong>允许的恰是满足 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmsub>\u003cmi>C\u003c/mi>\u003cmi>f\u003c/mi>\u003c/msub>\u003cmo>\u0026lt;\u003c/mo>\u003cmi mathvariant=\"normal\">∞\u003c/mi>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">C_f\u0026lt;\\infty\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span> 的 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmi>f\u003c/mi>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">f\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>，且最小 Lipschitz 常数为 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmsub>\u003cmi>C\u003c/mi>\u003cmi>f\u003c/mi>\u003c/msub>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">C_f\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>\u003c/strong>。\u003c/p>\n\u003cp>对每个允许的 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmi>f\u003c/mi>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">f\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>，给定 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmi>y\u003c/mi>\u003cmo>∈\u003c/mo>\u003cmi>E\u003c/mi>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">y\\in E\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>，令 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmsub>\u003cmi>x\u003c/mi>\u003cmrow>\u003cmi>f\u003c/mi>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmi>j\u003c/mi>\u003cmo stretchy=\"false\">)\u003c/mo>\u003c/mrow>\u003c/msub>\u003cmo>=\u003c/mo>\u003cmsub>\u003cmi>y\u003c/mi>\u003cmi>j\u003c/mi>\u003c/msub>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">x_{f(j)}=y_j\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>，并令其余位置的 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmsub>\u003cmi>x\u003c/mi>\u003cmi>m\u003c/mi>\u003c/msub>\u003cmo>=\u003c/mo>\u003cmn>0\u003c/mn>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">x_m=0\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>。这样得到的 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmi>x\u003c/mi>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">x\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span> 有界且 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmsub>\u003cmi>P\u003c/mi>\u003cmi>f\u003c/mi>\u003c/msub>\u003cmi>x\u003c/mi>\u003cmo>=\u003c/mo>\u003cmi>y\u003c/mi>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">P_fx=y\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>，故 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmsub>\u003cmi>T\u003c/mi>\u003cmi>f\u003c/mi>\u003c/msub>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">T_f\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span> 满射。\u003c/p>\n\u003cp>若 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmsub>\u003cmi>C\u003c/mi>\u003cmi>f\u003c/mi>\u003c/msub>\u003cmo>=\u003c/mo>\u003cmn>1\u003c/mn>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">C_f=1\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>，则 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmi>f\u003c/mi>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmi>n\u003c/mi>\u003cmo stretchy=\"false\">)\u003c/mo>\u003cmi mathvariant=\"normal\">/\u003c/mi>\u003cmi>n\u003c/mi>\u003cmo>→\u003c/mo>\u003cmn>1\u003c/mn>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">f(n)/n\\to1\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>。前 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmi>f\u003c/mi>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmi>n\u003c/mi>\u003cmo stretchy=\"false\">)\u003c/mo>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">f(n)\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span> 个位置中恰有 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmi>f\u003c/mi>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmi>n\u003c/mi>\u003cmo stretchy=\"false\">)\u003c/mo>\u003cmo>−\u003c/mo>\u003cmi>n\u003c/mi>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">f(n)-n\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span> 个位置未被前 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmi>n\u003c/mi>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">n\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span> 次取样选中，因此\n\u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\" display=\"block\">\u003csemantics>\u003cmrow>\u003cmfrac>\u003cmn>1\u003c/mn>\u003cmi>n\u003c/mi>\u003c/mfrac>\u003cmunderover>\u003cmo>∑\u003c/mo>\u003cmrow>\u003cmi>j\u003c/mi>\u003cmo>=\u003c/mo>\u003cmn>1\u003c/mn>\u003c/mrow>\u003cmi>n\u003c/mi>\u003c/munderover>\u003cmi mathvariant=\"normal\">∣\u003c/mi>\u003cmsub>\u003cmi>x\u003c/mi>\u003cmi>j\u003c/mi>\u003c/msub>\u003cmi mathvariant=\"normal\">∣\u003c/mi>\u003cmo>≤\u003c/mo>\u003cmfrac>\u003cmn>1\u003c/mn>\u003cmi>n\u003c/mi>\u003c/mfrac>\u003cmunderover>\u003cmo>∑\u003c/mo>\u003cmrow>\u003cmi>j\u003c/mi>\u003cmo>=\u003c/mo>\u003cmn>1\u003c/mn>\u003c/mrow>\u003cmi>n\u003c/mi>\u003c/munderover>\u003cmi mathvariant=\"normal\">∣\u003c/mi>\u003cmsub>\u003cmi>x\u003c/mi>\u003cmrow>\u003cmi>f\u003c/mi>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmi>j\u003c/mi>\u003cmo stretchy=\"false\">)\u003c/mo>\u003c/mrow>\u003c/msub>\u003cmi mathvariant=\"normal\">∣\u003c/mi>\u003cmo>+\u003c/mo>\u003cmfrac>\u003cmrow>\u003cmi>f\u003c/mi>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmi>n\u003c/mi>\u003cmo stretchy=\"false\">)\u003c/mo>\u003cmo>−\u003c/mo>\u003cmi>n\u003c/mi>\u003c/mrow>\u003cmi>n\u003c/mi>\u003c/mfrac>\u003cmi mathvariant=\"normal\">∥\u003c/mi>\u003cmi>x\u003c/mi>\u003cmsub>\u003cmi mathvariant=\"normal\">∥\u003c/mi>\u003cmi mathvariant=\"normal\">∞\u003c/mi>\u003c/msub>\u003cmi mathvariant=\"normal\">.\u003c/mi>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">\n\\frac1n\\sum_{j=1}^n |x_j|\n\\le \\frac1n\\sum_{j=1}^n |x_{f(j)}|\n+\\frac{f(n)-n}{n}\\|x\\|_\\infty.\n\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>\n取上极限并结合 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmi>ρ\u003c/mi>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmsub>\u003cmi>P\u003c/mi>\u003cmi>f\u003c/mi>\u003c/msub>\u003cmi>x\u003c/mi>\u003cmo stretchy=\"false\">)\u003c/mo>\u003cmo>≤\u003c/mo>\u003cmi>ρ\u003c/mi>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmi>x\u003c/mi>\u003cmo stretchy=\"false\">)\u003c/mo>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">\\rho(P_fx)\\le\\rho(x)\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>，得到 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmi>ρ\u003c/mi>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmsub>\u003cmi>P\u003c/mi>\u003cmi>f\u003c/mi>\u003c/msub>\u003cmi>x\u003c/mi>\u003cmo stretchy=\"false\">)\u003c/mo>\u003cmo>=\u003c/mo>\u003cmi>ρ\u003c/mi>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmi>x\u003c/mi>\u003cmo stretchy=\"false\">)\u003c/mo>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">\\rho(P_fx)=\\rho(x)\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>，故 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmsub>\u003cmi>T\u003c/mi>\u003cmi>f\u003c/mi>\u003c/msub>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">T_f\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span> 是等距双射。若 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmn>1\u003c/mn>\u003cmo>\u0026lt;\u003c/mo>\u003cmsub>\u003cmi>C\u003c/mi>\u003cmi>f\u003c/mi>\u003c/msub>\u003cmo>\u0026lt;\u003c/mo>\u003cmi mathvariant=\"normal\">∞\u003c/mi>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">1\u0026lt;C_f\u0026lt;\\infty\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>，取 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmi>x\u003c/mi>\u003cmo>=\u003c/mo>\u003cmsub>\u003cmn mathvariant=\"bold\">1\u003c/mn>\u003cmrow>\u003cmi mathvariant=\"double-struck\">N\u003c/mi>\u003cmo>∖\u003c/mo>\u003cmi>f\u003c/mi>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmi mathvariant=\"double-struck\">N\u003c/mi>\u003cmo stretchy=\"false\">)\u003c/mo>\u003c/mrow>\u003c/msub>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">x=\\mathbf1_{\\mathbb N\\setminus f(\\mathbb N)}\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>。此时 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmsub>\u003cmi>P\u003c/mi>\u003cmi>f\u003c/mi>\u003c/msub>\u003cmi>x\u003c/mi>\u003cmo>=\u003c/mo>\u003cmn>0\u003c/mn>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">P_fx=0\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>，而前 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmi>f\u003c/mi>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmi>n\u003c/mi>\u003cmo stretchy=\"false\">)\u003c/mo>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">f(n)\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span> 项中恰有 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmi>f\u003c/mi>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmi>n\u003c/mi>\u003cmo stretchy=\"false\">)\u003c/mo>\u003cmo>−\u003c/mo>\u003cmi>n\u003c/mi>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">f(n)-n\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span> 项等于 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmn>1\u003c/mn>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">1\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>，所以\n\u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\" display=\"block\">\u003csemantics>\u003cmrow>\u003cmi>ρ\u003c/mi>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmi>x\u003c/mi>\u003cmo stretchy=\"false\">)\u003c/mo>\u003cmo>≥\u003c/mo>\u003cmunder>\u003cmrow>\u003cmi mathvariant=\"normal\">lim sup\u003c/mi>\u003cmo>⁡\u003c/mo>\u003c/mrow>\u003cmrow>\u003cmi>n\u003c/mi>\u003cmo>→\u003c/mo>\u003cmi mathvariant=\"normal\">∞\u003c/mi>\u003c/mrow>\u003c/munder>\u003cmfrac>\u003cmrow>\u003cmi>f\u003c/mi>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmi>n\u003c/mi>\u003cmo stretchy=\"false\">)\u003c/mo>\u003cmo>−\u003c/mo>\u003cmi>n\u003c/mi>\u003c/mrow>\u003cmrow>\u003cmi>f\u003c/mi>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmi>n\u003c/mi>\u003cmo stretchy=\"false\">)\u003c/mo>\u003c/mrow>\u003c/mfrac>\u003cmo>=\u003c/mo>\u003cmn>1\u003c/mn>\u003cmo>−\u003c/mo>\u003cmfrac>\u003cmn>1\u003c/mn>\u003cmsub>\u003cmi>C\u003c/mi>\u003cmi>f\u003c/mi>\u003c/msub>\u003c/mfrac>\u003cmo>\u0026gt;\u003c/mo>\u003cmn>0.\u003c/mn>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">\n\\rho(x)\\ge \\limsup_{n\\to\\infty}\\frac{f(n)-n}{f(n)}\n=1-\\frac1{C_f}\u0026gt;0.\n\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>\n因此，\u003cstrong>\u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmsub>\u003cmi>T\u003c/mi>\u003cmi>f\u003c/mi>\u003c/msub>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">T_f\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span> 当且仅当 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmsub>\u003cmi>C\u003c/mi>\u003cmi>f\u003c/mi>\u003c/msub>\u003cmo>=\u003c/mo>\u003cmn>1\u003c/mn>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">C_f=1\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span> 时单射\u003c/strong>。\u003c/p>\n\u003ch2>2. 迭代增长率与全部可能的有序对\u003c/h2>\n\u003cp>因为 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmsubsup>\u003cmi>T\u003c/mi>\u003cmi>f\u003c/mi>\u003cmi>k\u003c/mi>\u003c/msubsup>\u003cmo>=\u003c/mo>\u003cmsub>\u003cmi>T\u003c/mi>\u003cmsup>\u003cmi>f\u003c/mi>\u003cmrow>\u003cmo>∘\u003c/mo>\u003cmi>k\u003c/mi>\u003c/mrow>\u003c/msup>\u003c/msub>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">T_f^k=T_{f^{\\circ k}}\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>，第一问给出\n\u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\" display=\"block\">\u003csemantics>\u003cmrow>\u003cmsub>\u003cmi>L\u003c/mi>\u003cmi>k\u003c/mi>\u003c/msub>\u003cmo>=\u003c/mo>\u003cmunder>\u003cmrow>\u003cmi mathvariant=\"normal\">lim sup\u003c/mi>\u003cmo>⁡\u003c/mo>\u003c/mrow>\u003cmrow>\u003cmi>n\u003c/mi>\u003cmo>→\u003c/mo>\u003cmi mathvariant=\"normal\">∞\u003c/mi>\u003c/mrow>\u003c/munder>\u003cmfrac>\u003cmrow>\u003cmsup>\u003cmi>f\u003c/mi>\u003cmrow>\u003cmo>∘\u003c/mo>\u003cmi>k\u003c/mi>\u003c/mrow>\u003c/msup>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmi>n\u003c/mi>\u003cmo stretchy=\"false\">)\u003c/mo>\u003c/mrow>\u003cmi>n\u003c/mi>\u003c/mfrac>\u003cmi mathvariant=\"normal\">.\u003c/mi>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">\nL_k=\\limsup_{n\\to\\infty}\\frac{f^{\\circ k}(n)}n.\n\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>\n复合映射的 Lipschitz 常数满足 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmsub>\u003cmi>L\u003c/mi>\u003cmrow>\u003cmi>k\u003c/mi>\u003cmo>+\u003c/mo>\u003cmi>m\u003c/mi>\u003c/mrow>\u003c/msub>\u003cmo>≤\u003c/mo>\u003cmsub>\u003cmi>L\u003c/mi>\u003cmi>k\u003c/mi>\u003c/msub>\u003cmsub>\u003cmi>L\u003c/mi>\u003cmi>m\u003c/mi>\u003c/msub>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">L_{k+m}\\le L_kL_m\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>，故 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmn>1\u003c/mn>\u003cmo>≤\u003c/mo>\u003cmsub>\u003cmi>L\u003c/mi>\u003cmi>k\u003c/mi>\u003c/msub>\u003cmo>≤\u003c/mo>\u003cmsubsup>\u003cmi>L\u003c/mi>\u003cmn>1\u003c/mn>\u003cmi>k\u003c/mi>\u003c/msubsup>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">1\\le L_k\\le L_1^k\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>。置 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmsub>\u003cmi>L\u003c/mi>\u003cmn>0\u003c/mn>\u003c/msub>\u003cmo>=\u003c/mo>\u003cmn>1\u003c/mn>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">L_0=1\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>。固定 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmi>m\u003c/mi>\u003cmo>≥\u003c/mo>\u003cmn>1\u003c/mn>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">m\\ge1\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>，将 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmi>k\u003c/mi>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">k\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span> 写为 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmi>k\u003c/mi>\u003cmo>=\u003c/mo>\u003cmi>q\u003c/mi>\u003cmi>m\u003c/mi>\u003cmo>+\u003c/mo>\u003cmi>s\u003c/mi>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">k=qm+s\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>，其中 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmn>0\u003c/mn>\u003cmo>≤\u003c/mo>\u003cmi>s\u003c/mi>\u003cmo>\u0026lt;\u003c/mo>\u003cmi>m\u003c/mi>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">0\\le s\u0026lt;m\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>，则\n\u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\" display=\"block\">\u003csemantics>\u003cmrow>\u003cmsubsup>\u003cmi>L\u003c/mi>\u003cmi>k\u003c/mi>\u003cmrow>\u003cmn>1\u003c/mn>\u003cmi mathvariant=\"normal\">/\u003c/mi>\u003cmi>k\u003c/mi>\u003c/mrow>\u003c/msubsup>\u003cmo>≤\u003c/mo>\u003cmsubsup>\u003cmi>L\u003c/mi>\u003cmi>m\u003c/mi>\u003cmrow>\u003cmi>q\u003c/mi>\u003cmi mathvariant=\"normal\">/\u003c/mi>\u003cmi>k\u003c/mi>\u003c/mrow>\u003c/msubsup>\u003cmsup>\u003cmrow>\u003cmo fence=\"true\">(\u003c/mo>\u003cmunder>\u003cmrow>\u003cmi>max\u003c/mi>\u003cmo>⁡\u003c/mo>\u003c/mrow>\u003cmrow>\u003cmn>0\u003c/mn>\u003cmo>≤\u003c/mo>\u003cmi>j\u003c/mi>\u003cmo>\u0026lt;\u003c/mo>\u003cmi>m\u003c/mi>\u003c/mrow>\u003c/munder>\u003cmsub>\u003cmi>L\u003c/mi>\u003cmi>j\u003c/mi>\u003c/msub>\u003cmo fence=\"true\">)\u003c/mo>\u003c/mrow>\u003cmrow>\u003cmn>1\u003c/mn>\u003cmi mathvariant=\"normal\">/\u003c/mi>\u003cmi>k\u003c/mi>\u003c/mrow>\u003c/msup>\u003cmi mathvariant=\"normal\">.\u003c/mi>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">\nL_k^{1/k}\\le L_m^{q/k}\\left(\\max_{0\\le j\u0026lt;m}L_j\\right)^{1/k}.\n\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>\n令 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmi>k\u003c/mi>\u003cmo>→\u003c/mo>\u003cmi mathvariant=\"normal\">∞\u003c/mi>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">k\\to\\infty\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>，得到 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmsub>\u003cmrow>\u003cmi mathvariant=\"normal\">lim sup\u003c/mi>\u003cmo>⁡\u003c/mo>\u003c/mrow>\u003cmi>k\u003c/mi>\u003c/msub>\u003cmsubsup>\u003cmi>L\u003c/mi>\u003cmi>k\u003c/mi>\u003cmrow>\u003cmn>1\u003c/mn>\u003cmi mathvariant=\"normal\">/\u003c/mi>\u003cmi>k\u003c/mi>\u003c/mrow>\u003c/msubsup>\u003cmo>≤\u003c/mo>\u003cmsubsup>\u003cmi>L\u003c/mi>\u003cmi>m\u003c/mi>\u003cmrow>\u003cmn>1\u003c/mn>\u003cmi mathvariant=\"normal\">/\u003c/mi>\u003cmi>m\u003c/mi>\u003c/mrow>\u003c/msubsup>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">\\limsup_k L_k^{1/k}\\le L_m^{1/m}\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>。对 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmi>m\u003c/mi>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">m\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span> 取下确界，再用 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmsub>\u003cmrow>\u003cmi mathvariant=\"normal\">lim inf\u003c/mi>\u003cmo>⁡\u003c/mo>\u003c/mrow>\u003cmi>k\u003c/mi>\u003c/msub>\u003cmsubsup>\u003cmi>L\u003c/mi>\u003cmi>k\u003c/mi>\u003cmrow>\u003cmn>1\u003c/mn>\u003cmi mathvariant=\"normal\">/\u003c/mi>\u003cmi>k\u003c/mi>\u003c/mrow>\u003c/msubsup>\u003cmo>≥\u003c/mo>\u003cmsub>\u003cmrow>\u003cmi>inf\u003c/mi>\u003cmo>⁡\u003c/mo>\u003c/mrow>\u003cmrow>\u003cmi>m\u003c/mi>\u003cmo>≥\u003c/mo>\u003cmn>1\u003c/mn>\u003c/mrow>\u003c/msub>\u003cmsubsup>\u003cmi>L\u003c/mi>\u003cmi>m\u003c/mi>\u003cmrow>\u003cmn>1\u003c/mn>\u003cmi mathvariant=\"normal\">/\u003c/mi>\u003cmi>m\u003c/mi>\u003c/mrow>\u003c/msubsup>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">\\liminf_k L_k^{1/k}\\ge\\inf_{m\\ge1}L_m^{1/m}\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>，可知\n\u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\" display=\"block\">\u003csemantics>\u003cmrow>\u003cmsub>\u003cmi>R\u003c/mi>\u003cmi>f\u003c/mi>\u003c/msub>\u003cmo>=\u003c/mo>\u003cmunder>\u003cmrow>\u003cmi>lim\u003c/mi>\u003cmo>⁡\u003c/mo>\u003c/mrow>\u003cmrow>\u003cmi>k\u003c/mi>\u003cmo>→\u003c/mo>\u003cmi mathvariant=\"normal\">∞\u003c/mi>\u003c/mrow>\u003c/munder>\u003cmsubsup>\u003cmi>L\u003c/mi>\u003cmi>k\u003c/mi>\u003cmrow>\u003cmn>1\u003c/mn>\u003cmi mathvariant=\"normal\">/\u003c/mi>\u003cmi>k\u003c/mi>\u003c/mrow>\u003c/msubsup>\u003cmo>=\u003c/mo>\u003cmunder>\u003cmrow>\u003cmi>inf\u003c/mi>\u003cmo>⁡\u003c/mo>\u003c/mrow>\u003cmrow>\u003cmi>m\u003c/mi>\u003cmo>≥\u003c/mo>\u003cmn>1\u003c/mn>\u003c/mrow>\u003c/munder>\u003cmsubsup>\u003cmi>L\u003c/mi>\u003cmi>m\u003c/mi>\u003cmrow>\u003cmn>1\u003c/mn>\u003cmi mathvariant=\"normal\">/\u003c/mi>\u003cmi>m\u003c/mi>\u003c/mrow>\u003c/msubsup>\u003cmo separator=\"true\">,\u003c/mo>\u003cmspace width=\"2em\"/>\u003cmn>1\u003c/mn>\u003cmo>≤\u003c/mo>\u003cmsub>\u003cmi>R\u003c/mi>\u003cmi>f\u003c/mi>\u003c/msub>\u003cmo>≤\u003c/mo>\u003cmsub>\u003cmi>L\u003c/mi>\u003cmn>1\u003c/mn>\u003c/msub>\u003cmo>\u0026lt;\u003c/mo>\u003cmi mathvariant=\"normal\">∞\u003c/mi>\u003cmi mathvariant=\"normal\">.\u003c/mi>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">\nR_f=\\lim_{k\\to\\infty}L_k^{1/k}=\\inf_{m\\ge1}L_m^{1/m},\n\\qquad 1\\le R_f\\le L_1\u0026lt;\\infty.\n\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>\u003c/p>\n\u003cp>给定任意 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmn>1\u003c/mn>\u003cmo>≤\u003c/mo>\u003cmi>r\u003c/mi>\u003cmo>≤\u003c/mo>\u003cmi mathvariant=\"normal\">ℓ\u003c/mi>\u003cmo>\u0026lt;\u003c/mo>\u003cmi mathvariant=\"normal\">∞\u003c/mi>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">1\\le r\\le\\ell\u0026lt;\\infty\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>，令\n\u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\" display=\"block\">\u003csemantics>\u003cmrow>\u003cmi>c\u003c/mi>\u003cmo>=\u003c/mo>\u003cmi mathvariant=\"normal\">ℓ\u003c/mi>\u003cmo>−\u003c/mo>\u003cmn>1\u003c/mn>\u003cmo separator=\"true\">,\u003c/mo>\u003cmspace width=\"2em\"/>\u003cmsub>\u003cmi>a\u003c/mi>\u003cmi>i\u003c/mi>\u003c/msub>\u003cmo>=\u003c/mo>\u003cmsup>\u003cmn>2\u003c/mn>\u003cmsup>\u003cmi>i\u003c/mi>\u003cmn>2\u003c/mn>\u003c/msup>\u003c/msup>\u003cmspace width=\"1em\"/>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmi>i\u003c/mi>\u003cmo>≥\u003c/mo>\u003cmn>0\u003c/mn>\u003cmo stretchy=\"false\">)\u003c/mo>\u003cmo separator=\"true\">,\u003c/mo>\u003cmspace width=\"2em\"/>\u003cmi>a\u003c/mi>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmi>n\u003c/mi>\u003cmo stretchy=\"false\">)\u003c/mo>\u003cmo>=\u003c/mo>\u003cmi>max\u003c/mi>\u003cmo>⁡\u003c/mo>\u003cmo stretchy=\"false\">{\u003c/mo>\u003cmsub>\u003cmi>a\u003c/mi>\u003cmi>i\u003c/mi>\u003c/msub>\u003cmo>:\u003c/mo>\u003cmsub>\u003cmi>a\u003c/mi>\u003cmi>i\u003c/mi>\u003c/msub>\u003cmo>≤\u003c/mo>\u003cmi>n\u003c/mi>\u003cmo stretchy=\"false\">}\u003c/mo>\u003cmo separator=\"true\">,\u003c/mo>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">\nc=\\ell-1,\\qquad a_i=2^{i^2}\\quad(i\\ge0),\\qquad\na(n)=\\max\\{a_i:a_i\\le n\\},\n\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>\n并定义\n\u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\" display=\"block\">\u003csemantics>\u003cmrow>\u003cmi>f\u003c/mi>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmi>n\u003c/mi>\u003cmo stretchy=\"false\">)\u003c/mo>\u003cmo>=\u003c/mo>\u003cmi>n\u003c/mi>\u003cmo>+\u003c/mo>\u003cmi>max\u003c/mi>\u003cmo>⁡\u003c/mo>\u003cmo fence=\"true\" stretchy=\"true\" minsize=\"1.2em\" maxsize=\"1.2em\">{\u003c/mo>\u003cmo stretchy=\"false\">⌊\u003c/mo>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmi>r\u003c/mi>\u003cmo>−\u003c/mo>\u003cmn>1\u003c/mn>\u003cmo stretchy=\"false\">)\u003c/mo>\u003cmi>n\u003c/mi>\u003cmo stretchy=\"false\">⌋\u003c/mo>\u003cmo separator=\"true\">,\u003c/mo>\u003cmtext> \u003c/mtext>\u003cmo stretchy=\"false\">⌊\u003c/mo>\u003cmi>c\u003c/mi>\u003cmtext> \u003c/mtext>\u003cmi>a\u003c/mi>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmi>n\u003c/mi>\u003cmo stretchy=\"false\">)\u003c/mo>\u003cmo stretchy=\"false\">⌋\u003c/mo>\u003cmo fence=\"true\" stretchy=\"true\" minsize=\"1.2em\" maxsize=\"1.2em\">}\u003c/mo>\u003cmi mathvariant=\"normal\">.\u003c/mi>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">\nf(n)=n+\\max\\bigl\\{\\lfloor(r-1)n\\rfloor,\\ \\lfloor c\\,a(n)\\rfloor\\bigr\\}.\n\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>\n两个取整项均随 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmi>n\u003c/mi>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">n\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span> 非减，故 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmi>f\u003c/mi>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">f\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span> 严格递增。由于 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmi>a\u003c/mi>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmi>n\u003c/mi>\u003cmo stretchy=\"false\">)\u003c/mo>\u003cmo>≤\u003c/mo>\u003cmi>n\u003c/mi>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">a(n)\\le n\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span> 且 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmi>r\u003c/mi>\u003cmo>−\u003c/mo>\u003cmn>1\u003c/mn>\u003cmo>≤\u003c/mo>\u003cmi>c\u003c/mi>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">r-1\\le c\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>，有 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmi>f\u003c/mi>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmi>n\u003c/mi>\u003cmo stretchy=\"false\">)\u003c/mo>\u003cmo>≤\u003c/mo>\u003cmi mathvariant=\"normal\">ℓ\u003c/mi>\u003cmi>n\u003c/mi>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">f(n)\\le\\ell n\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>。在 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmi>n\u003c/mi>\u003cmo>=\u003c/mo>\u003cmsub>\u003cmi>a\u003c/mi>\u003cmi>i\u003c/mi>\u003c/msub>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">n=a_i\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span> 时，\n\u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\" display=\"block\">\u003csemantics>\u003cmrow>\u003cmi>f\u003c/mi>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmsub>\u003cmi>a\u003c/mi>\u003cmi>i\u003c/mi>\u003c/msub>\u003cmo stretchy=\"false\">)\u003c/mo>\u003cmo>=\u003c/mo>\u003cmsub>\u003cmi>a\u003c/mi>\u003cmi>i\u003c/mi>\u003c/msub>\u003cmo>+\u003c/mo>\u003cmo stretchy=\"false\">⌊\u003c/mo>\u003cmi>c\u003c/mi>\u003cmsub>\u003cmi>a\u003c/mi>\u003cmi>i\u003c/mi>\u003c/msub>\u003cmo stretchy=\"false\">⌋\u003c/mo>\u003cmo separator=\"true\">,\u003c/mo>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">\nf(a_i)=a_i+\\lfloor c a_i\\rfloor,\n\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>\n所以 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmsub>\u003cmi>L\u003c/mi>\u003cmn>1\u003c/mn>\u003c/msub>\u003cmo>=\u003c/mo>\u003cmi mathvariant=\"normal\">ℓ\u003c/mi>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">L_1=\\ell\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>。又因 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmi>f\u003c/mi>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmi>n\u003c/mi>\u003cmo stretchy=\"false\">)\u003c/mo>\u003cmo>≥\u003c/mo>\u003cmi>r\u003c/mi>\u003cmi>n\u003c/mi>\u003cmo>−\u003c/mo>\u003cmn>1\u003c/mn>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">f(n)\\ge rn-1\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>，迭代得\n\u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\" display=\"block\">\u003csemantics>\u003cmrow>\u003cmsup>\u003cmi>f\u003c/mi>\u003cmrow>\u003cmo>∘\u003c/mo>\u003cmi>k\u003c/mi>\u003c/mrow>\u003c/msup>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmi>n\u003c/mi>\u003cmo stretchy=\"false\">)\u003c/mo>\u003cmo>≥\u003c/mo>\u003cmsup>\u003cmi>r\u003c/mi>\u003cmi>k\u003c/mi>\u003c/msup>\u003cmi>n\u003c/mi>\u003cmo>−\u003c/mo>\u003cmunderover>\u003cmo>∑\u003c/mo>\u003cmrow>\u003cmi>j\u003c/mi>\u003cmo>=\u003c/mo>\u003cmn>0\u003c/mn>\u003c/mrow>\u003cmrow>\u003cmi>k\u003c/mi>\u003cmo>−\u003c/mo>\u003cmn>1\u003c/mn>\u003c/mrow>\u003c/munderover>\u003cmsup>\u003cmi>r\u003c/mi>\u003cmi>j\u003c/mi>\u003c/msup>\u003cmo separator=\"true\">,\u003c/mo>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">\nf^{\\circ k}(n)\\ge r^k n-\\sum_{j=0}^{k-1}r^j,\n\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>\n从而 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmsub>\u003cmi>L\u003c/mi>\u003cmi>k\u003c/mi>\u003c/msub>\u003cmo>≥\u003c/mo>\u003cmsup>\u003cmi>r\u003c/mi>\u003cmi>k\u003c/mi>\u003c/msup>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">L_k\\ge r^k\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>。\u003c/p>\n\u003cp>为估计上界，固定 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmi>k\u003c/mi>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">k\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>，记 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmsub>\u003cmi>n\u003c/mi>\u003cmi>t\u003c/mi>\u003c/msub>\u003cmo>=\u003c/mo>\u003cmsup>\u003cmi>f\u003c/mi>\u003cmrow>\u003cmo>∘\u003c/mo>\u003cmi>t\u003c/mi>\u003c/mrow>\u003c/msup>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmi>n\u003c/mi>\u003cmo stretchy=\"false\">)\u003c/mo>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">n_t=f^{\\circ t}(n)\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>（\u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmn>0\u003c/mn>\u003cmo>≤\u003c/mo>\u003cmi>t\u003c/mi>\u003cmo>≤\u003c/mo>\u003cmi>k\u003c/mi>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">0\\le t\\le k\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>）。令 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmi>A\u003c/mi>\u003cmo>=\u003c/mo>\u003cmi>a\u003c/mi>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmsub>\u003cmi>n\u003c/mi>\u003cmi>k\u003c/mi>\u003c/msub>\u003cmo stretchy=\"false\">)\u003c/mo>\u003cmo>=\u003c/mo>\u003cmsub>\u003cmi>a\u003c/mi>\u003cmi>i\u003c/mi>\u003c/msub>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">A=a(n_k)=a_i\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>，并在 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmi>n\u003c/mi>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">n\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span> 足够大时令 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmi>B\u003c/mi>\u003cmo>=\u003c/mo>\u003cmsub>\u003cmi>a\u003c/mi>\u003cmrow>\u003cmi>i\u003c/mi>\u003cmo>−\u003c/mo>\u003cmn>1\u003c/mn>\u003c/mrow>\u003c/msub>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">B=a_{i-1}\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>。由 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmi>A\u003c/mi>\u003cmo>≤\u003c/mo>\u003cmsub>\u003cmi>n\u003c/mi>\u003cmi>k\u003c/mi>\u003c/msub>\u003cmo>≤\u003c/mo>\u003cmsup>\u003cmi mathvariant=\"normal\">ℓ\u003c/mi>\u003cmi>k\u003c/mi>\u003c/msup>\u003cmi>n\u003c/mi>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">A\\le n_k\\le\\ell^k n\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span> 可知\n\u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\" display=\"block\">\u003csemantics>\u003cmrow>\u003cmfrac>\u003cmi>B\u003c/mi>\u003cmi>n\u003c/mi>\u003c/mfrac>\u003cmo>≤\u003c/mo>\u003cmsup>\u003cmi mathvariant=\"normal\">ℓ\u003c/mi>\u003cmi>k\u003c/mi>\u003c/msup>\u003cmfrac>\u003cmsub>\u003cmi>a\u003c/mi>\u003cmrow>\u003cmi>i\u003c/mi>\u003cmo>−\u003c/mo>\u003cmn>1\u003c/mn>\u003c/mrow>\u003c/msub>\u003cmsub>\u003cmi>a\u003c/mi>\u003cmi>i\u003c/mi>\u003c/msub>\u003c/mfrac>\u003cmo>⟶\u003c/mo>\u003cmn>0\u003c/mn>\u003cmspace width=\"2em\"/>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmi>n\u003c/mi>\u003cmo>→\u003c/mo>\u003cmi mathvariant=\"normal\">∞\u003c/mi>\u003cmo stretchy=\"false\">)\u003c/mo>\u003cmo separator=\"true\">,\u003c/mo>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">\n\\frac Bn\\le \\ell^k\\frac{a_{i-1}}{a_i}\\longrightarrow0\n\\qquad(n\\to\\infty),\n\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>\n这里 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmsub>\u003cmi>n\u003c/mi>\u003cmi>k\u003c/mi>\u003c/msub>\u003cmo>≥\u003c/mo>\u003cmi>n\u003c/mi>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">n_k\\ge n\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span> 保证了 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmi>i\u003c/mi>\u003cmo>→\u003c/mo>\u003cmi mathvariant=\"normal\">∞\u003c/mi>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">i\\to\\infty\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>。设 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmi>s\u003c/mi>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">s\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span> 是满足 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmsub>\u003cmi>n\u003c/mi>\u003cmi>s\u003c/mi>\u003c/msub>\u003cmo>≥\u003c/mo>\u003cmi>A\u003c/mi>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">n_s\\ge A\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span> 的最小下标。对 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmi>t\u003c/mi>\u003cmo>\u0026lt;\u003c/mo>\u003cmi>s\u003c/mi>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">t\u0026lt;s\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>，有 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmi>a\u003c/mi>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmsub>\u003cmi>n\u003c/mi>\u003cmi>t\u003c/mi>\u003c/msub>\u003cmo stretchy=\"false\">)\u003c/mo>\u003cmo>≤\u003c/mo>\u003cmi>B\u003c/mi>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">a(n_t)\\le B\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>。对 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmi>s\u003c/mi>\u003cmo>≤\u003c/mo>\u003cmi>t\u003c/mi>\u003cmo>\u0026lt;\u003c/mo>\u003cmi>k\u003c/mi>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">s\\le t\u0026lt;k\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>，则有 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmi>a\u003c/mi>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmsub>\u003cmi>n\u003c/mi>\u003cmi>t\u003c/mi>\u003c/msub>\u003cmo stretchy=\"false\">)\u003c/mo>\u003cmo>≤\u003c/mo>\u003cmi>A\u003c/mi>\u003cmo>≤\u003c/mo>\u003cmsub>\u003cmi>n\u003c/mi>\u003cmi>s\u003c/mi>\u003c/msub>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">a(n_t)\\le A\\le n_s\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>，因为 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmsub>\u003cmi>n\u003c/mi>\u003cmi>t\u003c/mi>\u003c/msub>\u003cmo>≤\u003c/mo>\u003cmsub>\u003cmi>n\u003c/mi>\u003cmi>k\u003c/mi>\u003c/msub>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">n_t\\le n_k\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>。\u003c/p>\n\u003cp>定义式给出 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmi>f\u003c/mi>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmi>m\u003c/mi>\u003cmo stretchy=\"false\">)\u003c/mo>\u003cmo>≤\u003c/mo>\u003cmi>r\u003c/mi>\u003cmi>m\u003c/mi>\u003cmo>+\u003c/mo>\u003cmi>c\u003c/mi>\u003cmtext> \u003c/mtext>\u003cmi>a\u003c/mi>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmi>m\u003c/mi>\u003cmo stretchy=\"false\">)\u003c/mo>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">f(m)\\le rm+c\\,a(m)\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>，所以\n\u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\" display=\"block\">\u003csemantics>\u003cmrow>\u003cmfrac>\u003cmsub>\u003cmi>n\u003c/mi>\u003cmrow>\u003cmi>t\u003c/mi>\u003cmo>+\u003c/mo>\u003cmn>1\u003c/mn>\u003c/mrow>\u003c/msub>\u003cmsup>\u003cmi>r\u003c/mi>\u003cmrow>\u003cmi>t\u003c/mi>\u003cmo>+\u003c/mo>\u003cmn>1\u003c/mn>\u003c/mrow>\u003c/msup>\u003c/mfrac>\u003cmo>≤\u003c/mo>\u003cmfrac>\u003cmsub>\u003cmi>n\u003c/mi>\u003cmi>t\u003c/mi>\u003c/msub>\u003cmsup>\u003cmi>r\u003c/mi>\u003cmi>t\u003c/mi>\u003c/msup>\u003c/mfrac>\u003cmo>+\u003c/mo>\u003cmfrac>\u003cmrow>\u003cmi>c\u003c/mi>\u003cmtext> \u003c/mtext>\u003cmi>a\u003c/mi>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmsub>\u003cmi>n\u003c/mi>\u003cmi>t\u003c/mi>\u003c/msub>\u003cmo stretchy=\"false\">)\u003c/mo>\u003c/mrow>\u003cmsup>\u003cmi>r\u003c/mi>\u003cmrow>\u003cmi>t\u003c/mi>\u003cmo>+\u003c/mo>\u003cmn>1\u003c/mn>\u003c/mrow>\u003c/msup>\u003c/mfrac>\u003cmi mathvariant=\"normal\">.\u003c/mi>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">\n\\frac{n_{t+1}}{r^{t+1}}\\le \\frac{n_t}{r^t}+\\frac{c\\,a(n_t)}{r^{t+1}}.\n\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>\n在 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmi>t\u003c/mi>\u003cmo>\u0026lt;\u003c/mo>\u003cmi>s\u003c/mi>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">t\u0026lt;s\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span> 时，每个增量至多为 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmi>c\u003c/mi>\u003cmi>B\u003c/mi>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">cB\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>，故 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmsub>\u003cmi>n\u003c/mi>\u003cmi>s\u003c/mi>\u003c/msub>\u003cmi mathvariant=\"normal\">/\u003c/mi>\u003cmsup>\u003cmi>r\u003c/mi>\u003cmi>s\u003c/mi>\u003c/msup>\u003cmo>≤\u003c/mo>\u003cmi>n\u003c/mi>\u003cmo>+\u003c/mo>\u003cmi>c\u003c/mi>\u003cmi>k\u003c/mi>\u003cmi>B\u003c/mi>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">n_s/r^s\\le n+ckB\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>。在 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmi>s\u003c/mi>\u003cmo>≤\u003c/mo>\u003cmi>t\u003c/mi>\u003cmo>\u0026lt;\u003c/mo>\u003cmi>k\u003c/mi>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">s\\le t\u0026lt;k\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span> 时，由 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmi>r\u003c/mi>\u003cmo>≥\u003c/mo>\u003cmn>1\u003c/mn>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">r\\ge1\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>，每个增量至多为 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmi>c\u003c/mi>\u003cmtext> \u003c/mtext>\u003cmsub>\u003cmi>n\u003c/mi>\u003cmi>s\u003c/mi>\u003c/msub>\u003cmi mathvariant=\"normal\">/\u003c/mi>\u003cmsup>\u003cmi>r\u003c/mi>\u003cmi>s\u003c/mi>\u003c/msup>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">c\\,n_s/r^s\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>。因此\n\u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\" display=\"block\">\u003csemantics>\u003cmrow>\u003cmfrac>\u003cmsub>\u003cmi>n\u003c/mi>\u003cmi>k\u003c/mi>\u003c/msub>\u003cmsup>\u003cmi>r\u003c/mi>\u003cmi>k\u003c/mi>\u003c/msup>\u003c/mfrac>\u003cmo>≤\u003c/mo>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmn>1\u003c/mn>\u003cmo>+\u003c/mo>\u003cmi>c\u003c/mi>\u003cmi>k\u003c/mi>\u003cmo stretchy=\"false\">)\u003c/mo>\u003cmfrac>\u003cmsub>\u003cmi>n\u003c/mi>\u003cmi>s\u003c/mi>\u003c/msub>\u003cmsup>\u003cmi>r\u003c/mi>\u003cmi>s\u003c/mi>\u003c/msup>\u003c/mfrac>\u003cmo>≤\u003c/mo>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmn>1\u003c/mn>\u003cmo>+\u003c/mo>\u003cmi>c\u003c/mi>\u003cmi>k\u003c/mi>\u003cmo stretchy=\"false\">)\u003c/mo>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmi>n\u003c/mi>\u003cmo>+\u003c/mo>\u003cmi>c\u003c/mi>\u003cmi>k\u003c/mi>\u003cmi>B\u003c/mi>\u003cmo stretchy=\"false\">)\u003c/mo>\u003cmi mathvariant=\"normal\">.\u003c/mi>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">\n\\frac{n_k}{r^k}\\le(1+ck)\\frac{n_s}{r^s}\n\\le(1+ck)(n+ckB).\n\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>\n除以 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmi>n\u003c/mi>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">n\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span> 并取上极限，得到 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmsub>\u003cmi>L\u003c/mi>\u003cmi>k\u003c/mi>\u003c/msub>\u003cmo>≤\u003c/mo>\u003cmsup>\u003cmi>r\u003c/mi>\u003cmi>k\u003c/mi>\u003c/msup>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmn>1\u003c/mn>\u003cmo>+\u003c/mo>\u003cmi>c\u003c/mi>\u003cmi>k\u003c/mi>\u003cmo stretchy=\"false\">)\u003c/mo>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">L_k\\le r^k(1+ck)\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>。结合 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmsub>\u003cmi>L\u003c/mi>\u003cmi>k\u003c/mi>\u003c/msub>\u003cmo>≥\u003c/mo>\u003cmsup>\u003cmi>r\u003c/mi>\u003cmi>k\u003c/mi>\u003c/msup>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">L_k\\ge r^k\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>，取 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmi>k\u003c/mi>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">k\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span> 次方根即得 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmsub>\u003cmi>R\u003c/mi>\u003cmi>f\u003c/mi>\u003c/msub>\u003cmo>=\u003c/mo>\u003cmi>r\u003c/mi>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">R_f=r\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>。\u003c/p>\n\u003cp>因此，全部可能的有序对为\n\u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\" display=\"block\">\u003csemantics>\u003cmrow>\u003cmenclose notation=\"box\">\u003cmstyle scriptlevel=\"0\" displaystyle=\"false\">\u003cmstyle scriptlevel=\"0\" displaystyle=\"false\">\u003cmstyle scriptlevel=\"0\" displaystyle=\"true\">\u003cmrow>\u003cmo stretchy=\"false\">{\u003c/mo>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmi mathvariant=\"normal\">ℓ\u003c/mi>\u003cmo separator=\"true\">,\u003c/mo>\u003cmi>r\u003c/mi>\u003cmo stretchy=\"false\">)\u003c/mo>\u003cmo>∈\u003c/mo>\u003cmsup>\u003cmi mathvariant=\"double-struck\">R\u003c/mi>\u003cmn>2\u003c/mn>\u003c/msup>\u003cmo>:\u003c/mo>\u003cmn>1\u003c/mn>\u003cmo>≤\u003c/mo>\u003cmi>r\u003c/mi>\u003cmo>≤\u003c/mo>\u003cmi mathvariant=\"normal\">ℓ\u003c/mi>\u003cmo>\u0026lt;\u003c/mo>\u003cmi mathvariant=\"normal\">∞\u003c/mi>\u003cmo stretchy=\"false\">}\u003c/mo>\u003c/mrow>\u003c/mstyle>\u003c/mstyle>\u003c/mstyle>\u003c/menclose>\u003cmi mathvariant=\"normal\">.\u003c/mi>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">\n\\boxed{\\{(\\ell,r)\\in\\mathbb R^2:1\\le r\\le\\ell\u0026lt;\\infty\\}}.\n\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>\u003c/p>\n","source":"assets/content/59f9e6d8c441d2847b945b519908fb21d0b2ba1f4464b1a26472024db6869b31.html"});
